        purpose: "بحث مشكلة تراجع درجات التحصيل المدرسي في مادة الرياضيات",
        date: "2026-06-25",
        notes: "تم التنسيق لإلحاق الطالب بحلقات الدعم الدراسي مع توفير دليل لمراجعة المفاهيم المنزلية.",
        status: "ملغاة"
